import logging
from taf.internal.managedobject import ManagedObject
from taf.internal.portforwarding.forwarding_server import ForwardingServer


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Branch(ManagedObject):

    def __init__(self, nodes, **kwargs):
        super(Branch, self).__init__(**kwargs)
        self._nodes = nodes
        for node in self._nodes:
            self.add_prerequisite(node)

    @property
    def forwarding_server(self):
        for node in self._nodes:
            if isinstance(node, ForwardingServer):
                return node

        raise AttributeError("'{class_name}' object has no attribute 'forwarding_server'".format(
            class_name=self.__class__.__name__))

    @property
    def forwarding_port(self):
        return self.forwarding_server.port
